      final value = response[y][x];
      if (value < p.integer('harris_threshold')) {
        continue;
      }
      var peak = true;
      for (final q in neighbors((x, y), width, height)) {
        final other = response[q.$2][q.$1];
        if (other > value ||
            other == value && (q.$2 < y || q.$2 == y && q.$1 < x)) {
          peak = false;
          break;
        }
      }
      if (peak) {
        candidates.add(Corner((x, y), value));
      }
    }
